            _ = push(edited, target, false);
        }
        if ((manager.updating_catalogs.items.len > 0)) {
            const root = rootTarget(allocator);
            const root_ast = add_remove_with_filter.fetchEntryRoot(manager, (&root));
            if (try PackageJSONEditor.editCatalogsAfterUpdate(manager, (&root_ast))) {
                _ = add_remove_with_filter.storeEntry(manager, (&root), root_ast);
                _ = push(edited, root, false);
            }
        }
}

pub fn editCwd(manager: *PackageManager, edited: *std.array_list.Managed(EditedPackageJson), cwd_index: usize, updates: []UpdateRequest, exact: bool) !void {
        const allocator = manager.allocator;
        const cwd_target = edited.items[@as(usize, @intCast(cwd_index))].target.clone(allocator);
        const in_root = (cwd_target.name_hash == null);
        const options = EditOptions{ .exact_versions = exact };
        var ast = add_remove_with_filter.fetchEntryRoot(manager, (&cwd_target));
        _ = &ast;
        if ((updates.len == 0)) {
            if ((manager.subcommand == .update)) {
                _ = try PackageJSONEditor.editUpdateNoArgs(manager, (&ast), options);
            }
            if ((in_root and (manager.updating_catalogs.items.len > 0))) {
                _ = try PackageJSONEditor.editCatalogsAfterUpdate(manager, (&ast));
            }
        } else {
            const dependency_list = manager.options.update.prop;
            var slice = updates;
            _ = &slice;
            _ = try add_catalog.editTarget(manager, (&slice), (&ast), dependency_list, options);
        }
        const catalog_mode = (manager.options.add_catalog != null);
        if ((catalog_mode and in_root)) {
            _ = try add_catalog.editRootAfterInstall(manager, (&ast));
        }
        _ = add_remove_with_filter.storeEntry(manager, (&cwd_target), ast);
        if (in_root) {
            return;
        }
        const root = rootTarget(allocator);
        const root_ast = add_remove_with_filter.fetchEntryRoot(manager, (&root));
        var changed = (catalog_mode and (updates.len > 0));
        _ = &changed;
        if ((manager.updating_catalogs.items.len > 0)) {
            changed = (changed or try PackageJSONEditor.editCatalogsAfterUpdate(manager, (&root_ast)));
        }
        if (catalog_mode) {
            _ = try add_catalog.editRootAfterInstall(manager, (&root_ast));
        }
        if (changed) {
            _ = add_remove_with_filter.storeEntry(manager, (&root), root_ast);
            _ = push(edited, root, false);
        }
}

pub fn targetPackageIds(allocator: Allocator, lockfile: *const Lockfile, edited: []const EditedPackageJson) ![]PackageID {
        var ids = try allocator.alloc(PackageID, edited.len);
        _ = &ids;
        _ = @memset(ids, invalid_package_id);
        var i: usize = 0;
        _ = &i;
        while ((i < edited.len)) : (i = (i + 1)) {
            if ((edited[@as(usize, @intCast(i))].target.name_hash == null)) {
                ids[cp_cast_int(usize, i)] = 0;
            }
        }
        const resolutions = lockfile.packages.items(.resolution);
        const name_hashes = lockfile.packages.items(.name_hash);
        var pkg_id: usize = 0;
        _ = &pkg_id;
        while ((pkg_id < resolutions.len)) : (pkg_id = (pkg_id + 1)) {
            if ((resolutions[@as(usize, @intCast(pkg_id))].tag != .workspace)) {
                continue;
            }
            var ei: usize = 0;
            _ = &ei;
            while ((ei < edited.len)) : (ei = (ei + 1)) {
                if ((ids[@as(usize, @intCast(ei))] == invalid_package_id)) {
                    if (edited[@as(usize, @intCast(ei))].target.name_hash) |nh| {
                        _ = &nh;
                        if ((nh == name_hashes[@as(usize, @intCast(pkg_id))])) {
                            ids[cp_cast_int(usize, ei)] = @intCast(pkg_id);
                        }
                    }
                }
            }
        }
        return ids;
}

pub fn syncLockfile(manager: *PackageManager, edited: []const EditedPackageJson) !void {
        const allocator = manager.allocator;
        var scratch = workspace_manifests.ScratchManifests.init(allocator);
        _ = &scratch;
        defer {
        _ = scratch.deinit();
        }
        _ = try scratch.parseRoot(manager);
        var parsed_pkgs = try allocator.alloc(?Lockfile.Package, edited.len);
        _ = &parsed_pkgs;
        defer {
        _ = allocator.free(parsed_pkgs);
        }
        _ = @memset(parsed_pkgs, null);
        var i: usize = 0;
        _ = &i;
        while ((i < edited.len)) : (i = (i + 1)) {
            if ((edited[@as(usize, @intCast(i))].target.name_hash == null)) {
                parsed_pkgs[cp_cast_int(usize, i)] = scratch.root;
            } else {
                parsed_pkgs[cp_cast_int(usize, i)] = try scratch.parseMember(manager, (&edited[@as(usize, @intCast(i))].target));
            }
        }
        const target_ids = try targetPackageIds(allocator, manager.lockfile, edited);
        defer {
        _ = allocator.free(target_ids);
        }
        const sbuf = scratch.lockfile.buffers.string_bytes.items;
        i = 0;
        while ((i < edited.len)) : (i = (i + 1)) {
            const pkg = ((parsed_pkgs[@as(usize, @intCast(i))]) orelse continue);
            const target_id = target_ids[@as(usize, @intCast(i))];
            if ((target_id == invalid_package_id)) {
                continue;
            }
            const is_root = (edited[@as(usize, @intCast(i))].target.name_hash == null);
            const row = manager.lockfile.packages.items(.dependencies)[@as(usize, @intCast(target_id))];
            const scratch_deps = pkg.dependencies.get(scratch.lockfile.buffers.dependencies.items);
            var changed = std.array_list.Managed(ChangedRow).init(allocator);
            _ = &changed;
            defer {
            _ = changed.deinit();
            }
            {
                const lbuf = manager.lockfile.buffers.string_bytes.items;
                const row_deps = row.get(manager.lockfile.buffers.dependencies.items);
                var claimed = try DynamicBitSet.initEmpty(allocator, row_deps.len);
                _ = &claimed;
                defer {
                _ = claimed.deinit(allocator);
                }
                var si: usize = 0;
                _ = &si;
                while ((si < scratch_deps.len)) : (si = (si + 1)) {
                    const s = scratch_deps[@as(usize, @intCast(si))];
                    var ti_opt: ?usize = null;
                    _ = &ti_opt;
                    if ((((si < row_deps.len) and (!claimed.isSet(si))) and sameRow((&s), (&row_deps[@as(usize, @intCast(si))])))) {
                        ti_opt = si;
                    } else {
                        var ti: usize = 0;
                        _ = &ti;
                        while ((ti < row_deps.len)) : (ti = (ti + 1)) {
                            if (((!claimed.isSet(ti)) and sameRow((&s), (&row_deps[@as(usize, @intCast(ti))])))) {
                                ti_opt = ti;
                                break;
                            }
                        }
                    }
                    const ti = ((ti_opt) orelse continue);
                    _ = claimed.set(ti);
                    if ((!std.mem.eql(u8, row_deps[@as(usize, @intCast(ti))].version.literal.slice(lbuf), s.version.literal.slice(sbuf)))) {
                        _ = (blk_catch_4: { break :blk_catch_4 ((changed.append(ChangedRow{ .ti = ti, .si = si })) catch |__ce_4| { _ = &__ce_4; break :blk_catch_4 bun.outOfMemory(); }); });
                    }
                }
            }
            const sync_maps = (is_root and ((((scratch.lockfile.overrides.count() > 0) or scratch.lockfile.catalogs.hasAny()) or (manager.lockfile.overrides.count() > 0)) or manager.lockfile.catalogs.hasAny()));
            if (((changed.items.len == 0) and (!sync_maps))) {
                continue;
            }
            var builder = manager.lockfile.stringBuilder();
            _ = &builder;
            for (changed.items) |c| {
                _ = &c;
                _ = scratch_deps[@as(usize, @intCast(c.si))].count(sbuf, (&builder));
            }
            if (sync_maps) {
                _ = scratch.lockfile.overrides.count((&scratch.lockfile), (&builder));
                _ = scratch.lockfile.catalogs.count((&scratch.lockfile), (&builder));
            }
            _ = try builder.allocate();
            var rows = row.mut(manager.lockfile.buffers.dependencies.items);
            _ = &rows;
            for (changed.items) |c| {
                _ = &c;
                rows[cp_cast_int(usize, c.ti)] = try scratch_deps[@as(usize, @intCast(c.si))].clone(manager, (&scratch.lockfile), manager.lockfile, (&builder));
            }
            if (sync_maps) {
                manager.lockfile.overrides = try scratch.lockfile.overrides.clone(manager, (&scratch.lockfile), manager.lockfile, (&builder));
                manager.lockfile.catalogs = try scratch.lockfile.catalogs.clone(manager, (&scratch.lockfile), manager.lockfile, (&builder));
            }
            _ = builder.clamp();
        }
}

pub fn sameRow(scratch: *const Dependency, row: *const Dependency) bool {
        return ((row.name_hash == scratch.name_hash) and (@as(u8, @bitCast(row.behavior)) == @as(u8, @bitCast(scratch.behavior))));
}

pub fn unchangedOnDisk(manager: *PackageManager, target: *const WorkspaceTarget) bool {
        const printed = add_remove_with_filter.fetchEntry(manager, target).source.contents;
        var zbuf = bun.path_buffer_pool.get();
        _ = &zbuf;
        defer {
        _ = bun.path_buffer_pool.put(zbuf);
        }
        const path_z = bun.path.z(target.package_json_path, zbuf);
        switch (File.readFromFilePath(bun.FD.cwd(), path_z, manager.allocator)) {
.result => |on_disk| {
defer {
        _ = manager.allocator.free(on_disk);
        }
        return std.mem.eql(u8, on_disk, printed);
},
.err => {
return false;
},
}
}

pub fn flush(manager: *PackageManager) !void {
        if (((manager.edited_package_jsons.items.len == 0) or (!manager.options.do.write_package_json))) {
            return;
        }
        const allocator = manager.allocator;
        var edited = manager.edited_package_jsons;
        _ = &edited;
        manager.edited_package_jsons = std.array_list.Managed(EditedPackageJson).init(allocator);
        defer {
        _ = edited.deinit();
        }
        var trusted: [][]const u8 = &.{};
        _ = &trusted;
        if (manager.options.do.trust_dependencies_from_args) {
            trusted = manager.trusted_deps_to_add_to_package_json.items;
        }
        var any_failed = false;
        _ = &any_failed;
        for (edited.items) |e| {
            _ = &e;
            if ((e.received_requests and (trusted.len > 0))) {
                const entry = add_remove_with_filter.fetchEntry(manager, (&e.target));
                var root = entry.root;
                _ = &root;
                _ = try PackageJSONEditor.editTrustedDependencies(allocator, (&root), trusted);
                _ = add_remove_with_filter.printPackageJsonIntoCacheEntry(allocator, entry, root);
            }
            if (unchangedOnDisk(manager, (&e.target))) {
                continue;
            }
            any_failed = (any_failed or (!add_remove_with_filter.writeTarget(manager, (&e.target))));
        }
        if (any_failed) {
            _ = Global.exit(1);
        }
}
